B.azO=new A.o(B.dg,['<div style="text-align: center; color: white; font-family: \'Montserrat\'; padding: 20px;"><p style="font-size: 20px; line-height: 1.6;">Sorular\u0131n\u0131z i\xe7in l\xfctfen ileti\u015fime ge\xe7iniz. <br/><a href="mailto:info@dandungol.com" style="color: #cbffaa; text-decoration: none;">info@dandungol.com</a></p></div>','<div style="text-align: center; color: white; font-family: \'Montserrat\'; padding: 20px;"><p style="font-size: 20px; line-height: 1.6;">If you have any questions, please contact with us. <br/><a href="mailto:info@dandungol.com" style="color: #cbffaa; text-decoration: none;">info@dandungol.com</a>.</p></div>'],t.w)
B.azM=new A.o(B.dg,['<div style="text-align: center; color:white; font-family: \'Montserrat\'; font-weight: bold; letter-spacing: 1.5px;"><span style="font-size: 16px;">\u0130STANBUL\'DAK\u0130 </span><span style="font-size: 18px;">GER\xc7EK ROBOTLARI</span><br><span style="font-size: 18px;">D\xdcNYANIN HER YER\u0130NDEN</span><span style="font-size: 16px;"> KONTROL ET!</span></div>','<div style="text-align: center; color:white; font-family: \'Montserrat\'; font-weight: bold; letter-spacing: 1.5px;"><span style="font-size: 16px;">CONTROL </span><span style="font-size: 18px;">REAL ROBOTS</span><span style="font-size: 16px;"> IN ISTANBUL</span><br><span style="font-size: 16px;">FROM </span><span style="font-size: 18px;">WHERE YOU ARE ON EARTH!</span></div>'],t.w)
